RCH_st.name='RCH'; 
RCH_st.lat=23.37;
RCH_st.lon=85.33;
RCH_st.alt=0000;
RCH_st.env='Con';
RCH_st.footp='U';
%%
% data imported via the import tool from matlab
 RCH_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\RCH_2016-2026_Hour.csv", [2, Inf]);
RCH_rd_h.Properties.DimensionNames{1}='Time';
RCH_rd_h.Properties.VariableNames{2}='Ba1_A';
RCH_rd_h.Properties.VariableNames{3}='Ba2_A';
RCH_rd_h.Properties.VariableNames{4}='Ba3_A';
RCH_rd_h.Properties.VariableNames{5}='Ba4_A';
RCH_rd_h.Properties.VariableNames{6}='Ba5_A';
RCH_rd_h.Properties.VariableNames{7}='Ba6_A';
RCH_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(RCH_rd_h);
%%
RCH_rd=retime(RCH_rd_h,'daily',@nanmedian);
%%
datevec(RCH_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(RCH_rd.Time(end)) % end in 2022 June too short %[output:0c280ed0]
plotFigControl(RCH_rd,RCH_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
RCH_cal=compute_exp_D(RCH_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:600ff552] %[output:829f7b86] %[output:34c34e8e] %[output:91e2cbb3] %[output:8bb7dc0f] %[output:436907df]
plotFigControl_cal(RCH_cal,RCH_st.name); %[output:55008897] %[output:8ab30996] %[output:6393573f]
%%
%HOMOGENEITY

break_RCH_abs_BP=change_point_analysis_Def(RCH_rd,names_abs,0.05,'RCH','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:8d02ea43]
T_RCH_abs_BP=make_table_breakpoints_def(break_RCH_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:143c518b]
break_RCH_expA_BP=change_point_analysis_Def(RCH_cal,names_expA,0.05,'RCH','Absorption exponent'); %[output:455104ae] %[output:6c59b36a] %[output:85c29686] %[output:2e5e35fe]
T_RCH_expA_BP=make_table_breakpoints_def(break_RCH_expA_BP);




